import React, { useState } from "react";
import BaseLayout from "../../../layouts/BaseLayout";
import axios from "axios";
import "./InviteDoctor.css";
import { PhoneInput } from "react-international-phone";
import "react-international-phone/style.css";

const InviteDoctor = () => {
  // State for form fields
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [contact, setContact] = useState("");
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [loading, setLoading] = useState(false); // Add loading state

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Reset error and success messages
    setError(null);
    setSuccess(null);
    setLoading(true); // Set loading to true when the request is made

    try {
      // Make API request to send the invitation
      const response = await axios.post(
        "https://consultant-backend-jiwv.onrender.com/invite-doctor",
        {
          firstName,
          lastName,
          email,
          contact,
        }
      );

      if (response.data) {
        setSuccess("Doctor invitation sent successfully!");
        setFirstName("");
        setLastName("");
        setEmail("");
        setContact("");
      }
    } catch (err) {
      setError("Failed to send invitation. Please try again.");
    }

    setLoading(false); // Set loading to false after the request completes
  };

  return (
    <BaseLayout>
      {/* Container */}
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6">
        {/* Header Section */}
        <div className="w-full max-w-xl mb-10">
          <div className="bg-white border border-gray-300 p-4 rounded-lg shadow-md text-center">
            <h3 className="text-2xl font-bold text-gray-700" id="header">
              Invite New Doctor
            </h3>
          </div>
        </div>

        {/* Form Section */}
        <div className="w-full max-w-xl">
          <form
            onSubmit={handleSubmit}
            className="bg-white p-8 border border-gray-300 rounded-lg shadow-lg"
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* First Name Field */}
              <div>
                <label className="block text-gray-600 mb-2">First Name</label>
                <input
                  type="text"
                  value={firstName}
                  onChange={(e) => setFirstName(e.target.value)}
                  placeholder="First Name"
                  className="w-full p-2 border rounded focus:ring focus:border-blue-300"
                  required
                />
              </div>

              {/* Last Name Field */}
              <div>
                <label className="block text-gray-600 mb-2">Last Name</label>
                <input
                  type="text"
                  value={lastName}
                  onChange={(e) => setLastName(e.target.value)}
                  placeholder="Last Name"
                  className="w-full p-2 border rounded focus:ring focus:border-blue-300"
                  required
                />
              </div>

              {/* Email Field */}
              <div>
                <label className="block text-gray-600 mb-2">Email</label>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email"
                  className="w-full p-2 border rounded focus:ring focus:border-blue-300"
                  required
                />
              </div>

              {/* Phone Number Field */}
              <div>
                <label className="block text-gray-600 mb-2">Phone Number</label>
                <PhoneInput
                  defaultCountry="india"
                  value={contact}
                  onChange={(contact) => setContact(contact)}
                  placeholder="Phone Number"
                  className="w-full p-2 border rounded focus:ring focus:border-blue-300"
                  required
                />
              </div>
            </div>

            {/* Error and Success Messages */}
            {error && <p className="text-red-500 mt-4">{error}</p>}
            {success && <p className="text-green-500 mt-4">{success}</p>}

            {/* Submit Button */}
            <div className="flex justify-center mt-6">
              <button
                type="submit"
                className={`${
                  loading
                    ? "bg-gray-400 cursor-not-allowed"
                    : "bg-blue-500 hover:bg-blue-600"
                } text-white py-2 px-4 rounded flex justify-center items-center`}
                disabled={loading} // Disable the button when loading
              >
                {loading ? (
                  <svg
                    className="animate-spin h-5 w-5 text-white"
                    xmlns="http://www.w3.org/2000/svg"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    ></circle>
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8v8H4z"
                    ></path>
                  </svg>
                ) : (
                  "Invite Doctor"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </BaseLayout>
  );
};

export default InviteDoctor;
